// The Design Studio's node layer, on the GPU (`gpu-graph-slice-5-swap-the-design-studio-graph`).
//
// WHAT IT REPLACES, measured on the live page: 402 `.ds-node` boxes at ~6 DOM elements each. Style and
// layout are linear at ~19 µs per element (402 nodes ⇒ 99 ms, 8,002 ⇒ 1,051 ms), and one click cost
// 371-506 ms — ~218 ms of browser style/layout/paint plus ~153 ms of React reconciliation. Collapsing
// the layer to ONE canvas element removes both: React sees a single child, and the browser has nothing
// to lay out.
//
// IT LIVES IN `overlays`, NOT IN `children`. GraphCanvas puts `children` INSIDE the world layer, which
// is CSS-transformed — a canvas there would be raster-scaled and blurry, the same trap `#graph-zoom-blur`
// documents for `will-change: transform`. `overlays` is a sibling of the world layer inside the
// viewport, so this draws in untransformed screen space and applies the transform itself.
//
// IT READS THE TRANSFORM FROM THE DOM, NOT FROM REACT STATE, and that is not a shortcut — it is what
// #4140 requires. The pan writes the world layer's transform DIRECTLY and commits to React only on
// mouseup, so a canvas driven from `vp.view` would sit frozen through the whole drag while the DOM
// moved under it. Reading the world element's INLINE transform each frame tracks both paths by
// construction, and costs no style recalc because the pan writes it inline.
//
// ACCESSIBILITY IS O(1) DOM, and deliberately so. A canvas has no accessibility tree, and v1.0.52's
// theme is accessibility + TTS, so dropping it is not available. But rendering one focusable element
// per node would put the O(N) DOM straight back. Instead this is a `listbox` with ONE rendered
// `option` — the active one — addressed by `aria-activedescendant`; arrow keys move the cursor and the
// screen reader announces each node as it becomes active. Navigable, announced, and one element.
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import {
  createGraphRenderer,
  NODE_NORMAL,
  NODE_SELECTED,
  NODE_DIMMED,
  type GraphRenderer,
} from "@/shared/lib/graph/glGraphRenderer";
import { buildGlyphAtlas, type GlyphAtlas } from "@/shared/lib/graph/glyphAtlas";
import { cssColorToPacked, cssColorToRgba } from "@/shared/lib/graph/cssColor";

export interface GpuGraphNode {
  id: string;
  /** World-space top-left, matching what the DOM node layer uses. */
  x: number;
  y: number;
  w: number;
  h: number;
  /** Any CSS colour, including `var(--…)` — resolved once against the live cascade. */
  color: string;
  label: string;
  /** Announced to a screen reader in place of the visual sub-text. */
  description?: string;
}

export interface GraphGpuLayerProps {
  nodes: readonly GpuGraphNode[];
  selectedId?: string | null;
  relatedIds?: ReadonlySet<string>;
  onSelect?: (id: string) => void;
  /** Rendered instead when WebGL2 is unavailable — keep the DOM layer as the fallback. */
  fallback?: ReactNode;
  ariaLabel?: string;
}

/**
 * Can this host draw the graph at all?
 *
 * Asked by the PAGE, not by this component, and that is the point: the DOM fallback belongs inside the
 * world layer (where its world-space coordinates are transformed for it), while this canvas belongs in
 * the untransformed `overlays` slot. Only the page can put each in the right place, so it needs the
 * answer before it renders either.
 *
 * Probed once and cached — creating a context per call would leak one per render on a page that asks
 * during layout.
 */
let webgl2: boolean | null = null;
export function hasWebgl2(): boolean {
  if (webgl2 !== null) return webgl2;
  try {
    // Probes with the REAL constructor, not just `getContext`. The two can disagree — a driver that
    // hands out a context but refuses to link the shaders makes `getContext` say yes and
    // `createGraphRenderer` return null. The page would then hide its DOM layer (gpuOk true) while this
    // component rendered nothing (renderer null): a blank graph on exactly the machines least able to
    // afford one. Asking the same question both callers ask removes the disagreement rather than
    // handling it.
    const probe = createGraphRenderer(document.createElement("canvas"));
    webgl2 = !!probe;
    probe?.dispose();
  } catch {
    webgl2 = false;
  }
  return webgl2;
}

/** The atlas is per (font, size) and costs ~26 ms; module-level so a remount does not rebuild it. */
let sharedAtlas: GlyphAtlas | null = null;
let sharedAtlasKey = "";

function atlasFor(font: string): GlyphAtlas | null {
  if (sharedAtlas && sharedAtlasKey === font) return sharedAtlas;
  const a = buildGlyphAtlas(font, { fontSize: 40, spread: 6 });
  if (a) {
    sharedAtlas = a;
    sharedAtlasKey = font;
  }
  return a;
}

/**
 * Resolve any CSS colour — including `var(--role-primitive)` — to packed `0xAABBGGRR`.
 *
 * Goes through the live cascade rather than a lookup table because the roles are themed: a table would
 * be a second copy of the palette that drifts the first time a theme changes.
 */
/**
 * A CSS colour as 0..1 RGBA — what the renderer's palette uniforms take.
 *
 * Resolution is delegated to `cssColor`, which reads the pixel back off a 1x1 canvas instead of
 * parsing the string. This used to match `/rgba?\(...\)/` against the computed value, and EVERY
 * token in tokens.css is `oklch()` — which WebKitGTK serialises as `oklch(...)`. So the match failed
 * on every colour and both fallbacks below fired at once: a grey card with a grey label and a
 * near-white role dot, which is precisely what the graph rendered.
 */
function resolveRgba(css: string, probe: HTMLElement): number[] {
  return cssColorToRgba(css, probe, [0.5, 0.5, 0.5, 1]);
}

/** A CSS colour as packed 0xAABBGGRR — what the per-instance colour attribute takes. */
function resolveColor(css: string, probe: HTMLElement): number {
  return cssColorToPacked(css, probe, 0xffcccccc);
}

/** Parse `translate(3px, 4px) scale(2)` — the exact string `viewTransform` writes. */
export function parseWorldTransform(t: string): { tx: number; ty: number; scale: number } | null {
  if (!t) return null;
  const tr = /translate\(\s*(-?[\d.]+)px\s*,\s*(-?[\d.]+)px\s*\)/.exec(t);
  const sc = /scale\(\s*(-?[\d.]+)\s*\)/.exec(t);
  if (!tr && !sc) return null;
  return {
    tx: tr ? parseFloat(tr[1]) : 0,
    ty: tr ? parseFloat(tr[2]) : 0,
    scale: sc ? parseFloat(sc[1]) : 1,
  };
}

/** The world layer is the viewport child carrying an inline `transform` — the one #4140 writes. */
export function findWorldLayer(canvas: HTMLElement | null): HTMLElement | null {
  const vp = canvas?.parentElement;
  if (!vp) return null;
  for (const el of Array.from(vp.children)) {
    if (el === canvas) continue;
    const s = (el as HTMLElement).style?.transform;
    if (s && s.includes("translate")) return el as HTMLElement;
  }
  return null;
}

export function GraphGpuLayer({
  nodes, selectedId, relatedIds, onSelect, fallback, ariaLabel,
}: GraphGpuLayerProps): ReactNode {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const rendererRef = useRef<GraphRenderer | null>(null);
  const [unavailable, setUnavailable] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const nodesRef = useRef(nodes);
  nodesRef.current = nodes;

  const index = useMemo(() => new Map(nodes.map((n, i) => [n.id, i])), [nodes]);

  // Create the context ONCE. Re-creating it per node change would re-link two shader programs and
  // re-upload every buffer for what is usually a one-node edit.
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const r = createGraphRenderer(canvas, { edgeWidthPx: 1 });
    if (!r) {
      setUnavailable(true);
      return;
    }
    rendererRef.current = r;
    // The card palette, read from the LIVE cascade so the graph follows the theme. Hard-coding these
    // would be a second copy of the palette that drifts the first time a theme changes.
    // OPTIONAL CALL, deliberately. A record is updated in the STORE independently of the platform
    // modules it calls, so it can be newer than the renderer the running app was built with — which is
    // exactly what happened here: syncing this record before the renderer merged would have thrown
    // inside an effect and taken the page to the crash boundary. An older renderer simply keeps its
    // default palette.
    r.setPalette?.(
      resolveRgba("var(--bg-elev, var(--bg-soft))", canvas),
      resolveRgba("var(--border)", canvas),
      resolveRgba("var(--accent)", canvas),
      // The label takes the ordinary text colour, the same token .ds-node-name uses. It was a literal
      // near-white in the shader, which only read correctly while the card was drawn in the role colour.
      resolveRgba("var(--fg)", canvas),
    );
    const atlas = atlasFor(getComputedStyle(canvas).fontFamily || "system-ui, sans-serif");
    if (atlas) r.setAtlas(atlas);
    return () => {
      r.dispose();
      rendererRef.current = null;
    };
  }, []);

  // Upload geometry whenever the node set changes — O(n), and only then.
  useEffect(() => {
    const r = rendererRef.current;
    const canvas = canvasRef.current;
    if (!r || !canvas) return;
    const n = nodes.length;
    const xy = new Float32Array(n * 2);
    // INTERLEAVED [w,h] per node. A single scalar here is what drew every 172x58 card as a 172x172
    // square, swallowing the rows above and below it.
    const size = new Float32Array(n * 2);
    const rgba = new Uint32Array(n);
    for (let i = 0; i < n; i++) {
      const nd = nodes[i];
      // The DOM layer positions by TOP-LEFT; the renderer draws around a CENTRE. Getting this wrong
      // offsets every node by half a card, which looks like a layout bug rather than a coordinate one.
      xy[i * 2] = nd.x + nd.w / 2;
      xy[i * 2 + 1] = nd.y + nd.h / 2;
      size[i * 2] = nd.w;
      size[i * 2 + 1] = nd.h;
      rgba[i] = resolveColor(nd.color, canvas);
    }
    r.setNodes(xy, size, rgba, n);
    r.setLabels(nodes.map((nd) => nd.label));
  }, [nodes]);

  // Selection state is a per-instance byte: O(changed), never a re-upload. This is the specific fix for
  // the measured 371-506 ms click.
  const prevStates = useRef<Map<number, number>>(new Map());
  useEffect(() => {
    const r = rendererRef.current;
    if (!r) return;
    const want = new Map<number, number>();
    if (selectedId != null) {
      const i = index.get(selectedId);
      if (i !== undefined) want.set(i, NODE_SELECTED);
    }
    if (relatedIds) {
      for (const id of relatedIds) {
        const i = index.get(id);
        if (i !== undefined && !want.has(i)) want.set(i, NODE_DIMMED);
      }
    }
    for (const [i] of prevStates.current) if (!want.has(i)) r.setState(i, NODE_NORMAL);
    for (const [i, s] of want) r.setState(i, s);
    prevStates.current = want;
  }, [selectedId, relatedIds, index]);

  // One rAF loop, and it must not TOUCH LAYOUT.
  //
  // Reading `parentElement.clientWidth` here was a self-inflicted 58 ms per frame — measured on the live
  // page: a geometry read after any style invalidation forces a synchronous layout flush over the whole
  // document (0.205 ms when style is already clean, 58.1 ms when it is not). React re-rendering the
  // inspector on selection invalidates style, so every click paid a full layout on the very next frame —
  // reintroducing, from inside the fix, the exact cost this component exists to remove.
  //
  // A ResizeObserver reports the size instead, so the loop reads only the world layer's INLINE
  // `transform` string. That read is free: the imperative pan (#4140) writes it inline, so there is no
  // computed style to resolve and nothing to flush.
  const sizeRef = useRef({ w: 0, h: 0, dirty: true });
  useEffect(() => {
    const box = canvasRef.current?.parentElement;
    if (!box) return;
    const ro = new ResizeObserver((entries) => {
      const r = entries[0]?.contentRect;
      if (!r) return;
      sizeRef.current = { w: Math.round(r.width), h: Math.round(r.height), dirty: true };
    });
    ro.observe(box);
    return () => ro.disconnect();
  }, []);

  useEffect(() => {
    let raf = 0;
    let last = "";
    const tick = (): void => {
      raf = requestAnimationFrame(tick);
      const r = rendererRef.current;
      const canvas = canvasRef.current;
      if (!r || !canvas) return;
      const size = sizeRef.current;
      const world = findWorldLayer(canvas);
      const t = world?.style.transform ?? "";
      if (t === last && !size.dirty) return;
      last = t;
      if (size.dirty && size.w > 0 && size.h > 0) {
        size.dirty = false;
        canvas.style.width = `${size.w}px`;
        canvas.style.height = `${size.h}px`;
        r.resize(size.w, size.h, window.devicePixelRatio || 1);
      }
      const v = parseWorldTransform(t);
      if (v) r.setView(v);
      r.draw();
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  const onClick = useCallback(
    (e: React.MouseEvent<HTMLCanvasElement>) => {
      const r = rendererRef.current;
      const canvas = canvasRef.current;
      if (!r || !canvas) return;
      const rect = canvas.getBoundingClientRect();
      const i = r.pick(e.clientX - rect.left, e.clientY - rect.top);
      // A miss must NOT be swallowed: the page's backdrop handler clears the selection, and eating the
      // event here would make clicking empty space do nothing.
      if (i < 0) return;
      e.stopPropagation();
      setActiveIdx(i);
      onSelect?.(nodesRef.current[i].id);
    },
    [onSelect],
  );

  const onKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      const list = nodesRef.current;
      if (list.length === 0) return;
      let next = activeIdx;
      if (e.key === "ArrowRight" || e.key === "ArrowDown") next = Math.min(list.length - 1, activeIdx + 1);
      else if (e.key === "ArrowLeft" || e.key === "ArrowUp") next = Math.max(0, activeIdx - 1);
      else if (e.key === "Home") next = 0;
      else if (e.key === "End") next = list.length - 1;
      else if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        onSelect?.(list[activeIdx].id);
        return;
      } else return;
      e.preventDefault();
      setActiveIdx(next);
    },
    [activeIdx, onSelect],
  );

  if (unavailable) return fallback ?? null;

  const active = nodes[Math.min(activeIdx, Math.max(0, nodes.length - 1))];
  const canvasStyle: CSSProperties = { position: "absolute", inset: 0, display: "block", outline: "none" };
  // ONE rendered option, addressed by `aria-activedescendant`. A per-node element would be correct for
  // a screen reader and would reinstate exactly the O(N) DOM this component exists to remove.
  const srOnly: CSSProperties = { position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)", whiteSpace: "nowrap" };

  return (
    <>
      <canvas
        ref={canvasRef}
        style={canvasStyle}
        onClick={onClick}
        onKeyDown={onKeyDown}
        tabIndex={0}
        role="listbox"
        aria-label={ariaLabel ?? `Component graph, ${nodes.length} nodes`}
        aria-activedescendant={active ? `gpu-node-${active.id}` : undefined}
      />
      <div style={srOnly}>
        {active && (
          <div id={`gpu-node-${active.id}`} role="option" aria-selected={active.id === selectedId}>
            {active.label}
            {active.description ? `, ${active.description}` : ""}
          </div>
        )}
      </div>
    </>
  );
}
